import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (pos < buf.length && buf[pos] <= 32) pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > 32) pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= 32) pos++;
        boolean neg = buf[pos] == 45;
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > 32) r = r * 10 + (buf[pos++] - 48);
        return neg ? -r : r;
    }

    static int nextInt() { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        int[] odd = new int[n], even = new int[n];
        int no = 0, ne = 0;
        for (int i = 0; i < n; i++) {
            int v = nextInt();
            if (v % 2 != 0) odd[no++] = v;
            else even[ne++] = v;
        }
        StringBuilder out = new StringBuilder();
        int i = 0, j = 0;
        while (i < no || j < ne) {
            int v;
            if (j >= ne || (i < no && odd[i] < even[j])) v = odd[i++];
            else v = even[j++];
            if (out.length() > 0) out.append(' ');
            out.append(v);
        }
        System.out.println(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int64 {
	b := next()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	var r int64
	for _, c := range b {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	n := int(nextInt())
	var odd, even []int64
	for i := 0; i < n; i++ {
		if v := nextInt(); v%2 != 0 {
			odd = append(odd, v)
		} else {
			even = append(even, v)
		}
	}
	i, j, first := 0, 0, true
	for i < len(odd) || j < len(even) {
		var v int64
		if j >= len(even) || (i < len(odd) && odd[i] < even[j]) {
			v = odd[i]
			i++
		} else {
			v = even[j]
			j++
		}
		if !first {
			w.WriteByte(' ')
		}
		first = false
		w.WriteString(strconv.FormatInt(v, 10))
	}
	w.WriteByte('\n')
}
